import React from 'react';
import './BrandLogo.css';

// The original artwork in /public is the fallback; /public/brand holds WebP copies at two widths, generated by
// `npm run brand-assets`: 240px for standard screens (the logo shows at about 190–230px) and the full 587px
// artwork for high-density screens. The browser picks one from srcSet and `sizes`.
// Logo and favicon files keep their URLs when replaced and browsers cache them for a day, so bump this after
// swapping the artwork to make every browser fetch the new files.
export const BRAND_VERSION = '2';

const FILES = {
  color: {
    webp: (w: number) => `/brand/healthcredstat-logo-${w}.webp?v=${BRAND_VERSION}`,
    original: `/healthcredstat-logo.png?v=${BRAND_VERSION}`,
  },
  white: {
    webp: (w: number) => `/brand/healthcredstat-logo-white-${w}.webp?v=${BRAND_VERSION}`,
    original: `/healthcredstat-logo-white.png?v=${BRAND_VERSION}`,
  },
} as const;

interface BrandLogoProps {
  variant?: keyof typeof FILES;
  className?: string;
  /** Intrinsic size attributes; they reserve space so the page doesn't shift when the image loads. */
  width: number;
  height: number;
  loading?: 'eager' | 'lazy';
}

/** The HealthCredSTAT logo. */
export function BrandLogo({ variant = 'color', className, width, height, loading = 'lazy' }: BrandLogoProps) {
  const files = FILES[variant];
  return (
    <picture className="brand-logo">
      <source type="image/webp" srcSet={`${files.webp(240)} 240w, ${files.webp(587)} 587w`} sizes={`${width}px`} />
      <img
        src={files.original}
        alt="HealthCredSTAT"
        width={width}
        height={height}
        className={className}
        loading={loading}
        decoding="async"
      />
    </picture>
  );
}

export default BrandLogo;
